import { Group, Mesh, CylinderGeometry, TorusKnotGeometry, PlaneGeometry, AmbientLight, DirectionalLight, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
	uv,
	vec3,
	vec2,
	float,
	mix,
	clamp,
	step,
	subtract,
	divide,
	mul,
	length
} from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three/webgpu').Object3D}
 */
export default function createNode(config, ctx) {
	const { Group, Mesh, CylinderGeometry, TorusKnotGeometry, PlaneGeometry, AmbientLight, DirectionalLight, Color } = ctx.THREE;

	const root = new Group();

	/*** BACKDROP ***/
	const backdropGeo = new PlaneGeometry(7, 6);
	const gradStops = config.visualSpec?.gradientStops ?? config.colors?.gradientStops ?? [
		{ at: 0, hex: '#0b0b10' },
		{ at: 0.7, hex: '#101017' },
		{ at: 1, hex: '#16161d' }
	];

	// helper to convert hex string to vec3 node
	const hexToVec3Node = (hex) => {
		const c = new Color(hex);
		return vec3(float(c.r), float(c.g), float(c.b));
	};

	const color0 = hexToVec3Node(gradStops[0].hex);
	const color1 = hexToVec3Node(gradStops[1].hex);
	const color2 = hexToVec3Node(gradStops[2].hex);

	const uvY = uv().y;
	const t0 = clamp(divide(uvY, float(0.7)), float(0), float(1));
	const firstMix = mix(color0, color1, t0);
	const t1 = clamp(divide(subtract(uvY, float(0.7)), float(0.3)), float(0), float(1));
	const secondMix = mix(color1, color2, t1);
	const useSecond = step(float(0.7), uvY); // 0 below 0.7, 1 above
	const finalColor = mix(firstMix, secondMix, useSecond);

	const backdropMat = new MeshBasicNodeMaterial();
	backdropMat.colorNode = finalColor;
	const backdropMesh = new Mesh(backdropGeo, backdropMat);
	backdropMesh.position.z = -3;
	root.add(backdropMesh);

	/*** PEDESTAL ***/
	const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
	const pedestalMat = new MeshStandardNodeMaterial();
	pedestalMat.color = new Color('#14141a');
	pedestalMat.roughness = 0.7;
	pedestalMat.metalness = 0.35;
	const pedestalMesh = new Mesh(pedestalGeo, pedestalMat);
	// top face at y = -0.35 → center y = -0.35 - 0.25
	pedestalMesh.position.y = -0.6;
	root.add(pedestalMesh);

	/*** TORUS KNOT ***/
	const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
	const knotMat = new MeshStandardNodeMaterial();
	knotMat.color = new Color(0xffffff);
	knotMat.metalness = 0.55;
	knotMat.roughness = 0.55;
	knotMat.clearcoat = 0.22;
	knotMat.clearcoatRoughness = 0.35;
	knotMat.anisotropy = 0.9; // built‑in property
	const knotMesh = new Mesh(knotGeo, knotMat);
	knotMesh.position.set(0, 0.4, 0);
	root.add(knotMesh);

	// Load brushed‑metal roughness map and apply jittered roughness
	let brushedTex = null;
	if (config.imageUrl) {
		ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
			brushedTex = tex;
			knotMat.roughnessMap = tex;
			// roughnessNode = texture * 0.9 (center injection)
			const texNode = texture(tex);
			knotMat.roughnessNode = mul(texNode, float(0.9));
			// add a tiny jitter (noise) – approximate with random offset per frame
			const jitter = mul(float(Math.random() * 0.02), float(1.0));
			knotMat.roughnessNode = clamp(add(knotMat.roughnessNode, jitter), float(0.0), float(1.0));
			knotMat.needsUpdate = true;
		});
	}

	/*** CONTACT SHADOW ***/
	const shadowGeo = new PlaneGeometry(3, 3);
	const shadowMat = new MeshBasicNodeMaterial();
	shadowMat.transparent = true;
	shadowMat.side = ctx.THREE.DoubleSide;
	// radial opacity gradient
	const uvCenter = vec2(float(0.5), float(0.5));
	const dist = length(subtract(uv(), uvCenter));
	const falloff = clamp(1.0 - smoothstep(float(0.0), float(0.4 / 1.5), dist), float(0.0), float(1.0));
	shadowMat.opacityNode = mul(float(0.6), falloff);
	const shadowMesh = new Mesh(shadowGeo, shadowMat);
	shadowMesh.rotation.x = -Math.PI / 2;
	shadowMesh.position.y = -0.36;
	root.add(shadowMesh);

	/*** LIGHTING ***/
	const ambient = new AmbientLight(0xffffff, 0.6);
	root.add(ambient);

	const keyLight = new DirectionalLight(0xffffff, 1.2);
	keyLight.position.set(1, 2, 1);
	root.add(keyLight);

	const rimLight = new DirectionalLight(0xff2a38, 0.8);
	rimLight.position.set(-1, -0.5, -1);
	root.add(rimLight);

	/*** TEXT CONTENT ***/
	const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
	const textGroup = new Group();

	const defaultColors = {
		headline: '#e8ecf2',
		caption: '#e8ecf2'
	};

	const baselineOffsets = {
		headline: -1.2,
		caption: -1.6
	};

	items.forEach((item) => {
		const role = item.role ?? (item.typography?.fontWeight >= 600 ? 'headline' : 'caption');
		const fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : 18);
		const color = item.role?.color ?? defaultColors[role] ?? '#e8ecf2';
		const txt = ctx.fontAtlas.createText(item.text, {
			fontSize,
			color,
			align: 'center'
		});
		txt.position.y = baselineOffsets[role] ?? 0;
		textGroup.add(txt);
	});
	root.add(textGroup);

	/*** CINEMATIC PRIMITIVES ***/
	const appliedPrimitives = [];
	if (Array.isArray(config.cinematicPrimitives)) {
		config.cinematicPrimitives.forEach((prim) => {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				const instance = fn(root, prim.params ?? {});
				appliedPrimitives.push(instance);
			}
		});
	}

	/*** USERDATA & CLEANUP ***/
	root.userData.handlers = {};
	root.userData.cleanup = () => {
		// dispose geometries & materials
		const disposeRecursive = (obj) => {
			if (obj.geometry) obj.geometry.dispose();
			if (obj.material) {
				if (Array.isArray(obj.material)) {
					obj.material.forEach((m) => m.dispose());
				} else {
					obj.material.dispose();
				}
			}
			if (obj.children) obj.children.forEach(disposeRecursive);
		};
		disposeRecursive(root);

		// dispose loaded texture
		if (brushedTex) brushedTex.dispose();

		// cleanup primitives
		appliedPrimitives.forEach((inst) => {
			if (inst && typeof inst.cleanup === 'function') inst.cleanup();
		});

		// kill any GSAP timelines we might have created (none in this node)
		gsap.globalTimeline.clear();
	};

	return root;
}
